MOTIF_NAME = 'safe_pawn_break_threat'
MOTIF_DESCRIPTION = 'The side to move threatens a pawn break that would open lines against the opponent king, while the opponent has no comparable threat.'
def motif(fen: str) -> bool:
    import chess
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm

    # Find opponent king
    opp_king_sq = board.king(opp)
    if opp_king_sq is None:
        return False
    opp_kf = chess.square_file(opp_king_sq)
    opp_kr = chess.square_rank(opp_king_sq)

    # Define king zone for opponent (king square and adjacent squares)
    king_zone = set()
    for df in (-1, 0, 1):
        for dr in (-1, 0, 1):
            f = opp_kf + df
            r = opp_kr + dr
            if 0 <= f <= 7 and 0 <= r <= 7:
                king_zone.add(chess.square(f, r))

    # Helper: check if a pawn advance opens a line (file, rank, diagonal) toward king zone
    def pawn_advances_toward_king(pawn_sq, color):
        pf = chess.square_file(pawn_sq)
        pr = chess.square_rank(pawn_sq)
        direction = 1 if color == chess.WHITE else -1
        # One square advance
        target_sq = chess.square(pf, pr + direction)
        if 0 <= pr + direction <= 7:
            # Remove pawn temporarily to see what lines open
            board_copy = board.copy()
            board_copy.remove_piece_at(pawn_sq)
            # Check if any piece attacks king zone squares through the vacated file/diagonal
            for sq in king_zone:
                attackers = board_copy.attackers(color, sq)
                for att_sq in attackers:
                    piece = board_copy.piece_at(att_sq)
                    if piece and piece.piece_type in (chess.QUEEN, chess.ROOK, chess.BISHOP):
                        # Check line of sight
                        if board_copy.attacks(att_sq) & chess.SquareSet(1 << sq):
                            # Make sure the pawn move doesn't just expose the king
                            stm_king_sq = board.king(color)
                            if stm_king_sq is None or not board_copy.is_attacked_by(opp, stm_king_sq):
                                return True
        # Two square advance for pawns on starting rank
        start_rank = 1 if color == chess.WHITE else 6
        if pr == start_rank:
            target_sq = chess.square(pf, pr + 2*direction)
            if 0 <= pr + 2*direction <= 7:
                board_copy = board.copy()
                board_copy.remove_piece_at(pawn_sq)
                for sq in king_zone:
                    attackers = board_copy.attackers(color, sq)
                    for att_sq in attackers:
                        piece = board_copy.piece_at(att_sq)
                        if piece and piece.piece_type in (chess.QUEEN, chess.ROOK, chess.BISHOP):
                            if board_copy.attacks(att_sq) & chess.SquareSet(1 << sq):
                                stm_king_sq = board.king(color)
                                if stm_king_sq is None or not board_copy.is_attacked_by(opp, stm_king_sq):
                                    return True
        return False

    # Check if stm has a pawn break toward opponent king
    stm_has_break = False
    for pawn_sq in board.pieces(chess.PAWN, stm):
        if pawn_advances_toward_king(pawn_sq, stm):
            stm_has_break = True
            break

    if not stm_has_break:
        return False

    # Check if opponent has a pawn break toward stm king
    stm_king_sq = board.king(stm)
    if stm_king_sq is None:
        return False
    stm_kf = chess.square_file(stm_king_sq)
    stm_kr = chess.square_rank(stm_king_sq)
    stm_king_zone = set()
    for df in (-1, 0, 1):
        for dr in (-1, 0, 1):
            f = stm_kf + df
            r = stm_kr + dr
            if 0 <= f <= 7 and 0 <= r <= 7:
                stm_king_zone.add(chess.square(f, r))

    # Temporarily override king_zone for opponent check
    orig_king_zone = king_zone
    # Use a local function to check opp breaks
    def opp_pawn_advances_toward_king(pawn_sq, color):
        pf = chess.square_file(pawn_sq)
        pr = chess.square_rank(pawn_sq)
        direction = 1 if color == chess.WHITE else -1
        target_sq = chess.square(pf, pr + direction)
        if 0 <= pr + direction <= 7:
            board_copy = board.copy()
            board_copy.remove_piece_at(pawn_sq)
            for sq in stm_king_zone:
                attackers = board_copy.attackers(color, sq)
                for att_sq in attackers:
                    piece = board_copy.piece_at(att_sq)
                    if piece and piece.piece_type in (chess.QUEEN, chess.ROOK, chess.BISHOP):
                        if board_copy.attacks(att_sq) & chess.SquareSet(1 << sq):
                            opp_king_sq2 = board.king(color)
                            if opp_king_sq2 is None or not board_copy.is_attacked_by(stm, opp_king_sq2):
                                return True
        start_rank = 1 if color == chess.WHITE else 6
        if pr == start_rank:
            target_sq = chess.square(pf, pr + 2*direction)
            if 0 <= pr + 2*direction <= 7:
                board_copy = board.copy()
                board_copy.remove_piece_at(pawn_sq)
                for sq in stm_king_zone:
                    attackers = board_copy.attackers(color, sq)
                    for att_sq in attackers:
                        piece = board_copy.piece_at(att_sq)
                        if piece and piece.piece_type in (chess.QUEEN, chess.ROOK, chess.BISHOP):
                            if board_copy.attacks(att_sq) & chess.SquareSet(1 << sq):
                                opp_king_sq2 = board.king(color)
                                if opp_king_sq2 is None or not board_copy.is_attacked_by(stm, opp_king_sq2):
                                    return True
        return False

    for pawn_sq in board.pieces(chess.PAWN, opp):
        if opp_pawn_advances_toward_king(pawn_sq, opp):
            return False

    return True
